node.log(msg.topic);
const parts = msg.topic.split("/");
msg.topic = parts[1];
return msg;

const results = msg.payload;
if (!Array.isArray(results) || results.length === 0) return null;

const pulso = [], temp = [];

results.forEach(r => {
    const point = { x: new Date(r._time).getTime(), y: r._value };
    if (r.sensor === "pulso") pulso.push(point);
    else if (r.sensor === "temperatura") temp.push(point);
});

const m1 = { payload: [{ series: ["Pulso"], data: [pulso], labels: [""] }] };
const m2 = { payload: [{ series: ["Temperatura"], data: [temp], labels: [""] }] };

return [m1, m2];

msg.measurement = "sensors";
msg.payload = [{ value: Number(msg.payload) }, { sensor: msg.topic }];
return msg;

const data = msg.payload;
node.warn('FF recibió: ' + JSON.stringify(data) + ' trained=' + flow.get('ff_trained'));
const pulso = Number(data.pulso);
const temperatura = Number(data.temperatura);

if (isNaN(pulso) || isNaN(temperatura)) return null;
if (!flow.get('ff_trained')) return null;

msg.runData = {
    pulso: pulso / 100,
    temp: temperatura / 100
};

msg.originalData = { pulso, temperatura };
return msg;

const brainjs = global.get('brainjs');

if (msg.trainData) {
    const net = new brainjs.recurrent.LSTMTimeStep({
        inputSize: 2,
        hiddenLayers: [10],
        outputSize: 2
    });
    node.status({fill:'yellow',shape:'dot',text:'Entrenando...'});

    try {
        const res = net.train(msg.trainData, {
            iterations: 500,
            errorThresh: 0.01,
            learningRate: 0.005,
            log: false
        });
        flow.set('lstm_net_json', net.toJSON());
        node.status({fill:'green',shape:'dot',text:'Entrenada (err=' + res.error.toFixed(4) + ')'});
        msg.net = true;
        msg.result = res;
        return msg;
    } catch(e) {
        node.error('LSTM train: ' + e.message);
        node.status({fill:'red',shape:'dot',text:'Error'});
        return null;
    }
}

if (msg.runData) {
    const netJSON = flow.get('lstm_net_json');
    if (!netJSON) return null;

    try {
        const net = new brainjs.recurrent.LSTMTimeStep();
        net.fromJSON(netJSON);
        msg.decision = net.run(msg.runData);
        return msg;
    } catch(e) {
        node.error('LSTM run: ' + e.message);
        return null;
    }
}

return null;

const data = msg.payload;
const pulso = Number(data.pulso);
const temperatura = Number(data.temperatura);

if (isNaN(pulso) || isNaN(temperatura)) return null;
if (!flow.get('lstm_trained')) return null;

const buffer = flow.get('lstm_buffer') || [];
buffer.push({ pulso: pulso / 200, temp: temperatura / 50 });

if (buffer.length > 4) buffer.shift();
flow.set('lstm_buffer', buffer);

if (buffer.length < 3) return null;

msg.runData = buffer.slice();
msg.originalData = { pulso, temperatura };
return msg;

const decision = msg.decision;
if (!decision || decision.peligro === undefined) return null;

const peligro = decision.peligro;
const orig = msg.originalData || {};
const pct = (peligro * 100).toFixed(1);
const estado = peligro >= 0.5 ? 'PELIGRO' : 'NORMAL';
const color = peligro >= 0.5 ? '#c0392b' : '#27ae60';

msg.payload = '<div style="text-align:center;padding:10px">' +
  '<span style="font-size:28px;font-weight:bold;color:' + color + '">' + estado + '</span><br>' +
  '<span style="font-size:18px;color:#555">Confianza: ' + pct + '%</span><br>' +
  '<span style="font-size:14px;color:#888">Pulso: ' + (orig.pulso || '?') + ' bpm | Temp: ' + (orig.temperatura || '?') + '°C</span>' +
  '</div>';
return msg;

const decision = msg.decision;
if (decision === undefined || decision === null) return null;

let pulsoPred, tempPred;
if (typeof decision === 'object' && decision.pulso !== undefined) {
    pulsoPred = Math.round(decision.pulso * 200);
    tempPred = (decision.temp * 50).toFixed(1);
} else {
    const val = (typeof decision === 'number') ? decision : Number(decision);
    if (isNaN(val)) return null;
    pulsoPred = Math.round(val * 200);
    tempPred = null;
}

const orig = msg.originalData || {};
const alertaP = (pulsoPred > 100 || pulsoPred < 60);
const alertaT = tempPred !== null && (Number(tempPred) > 38 || Number(tempPred) < 35.5);
const alerta = alertaP || alertaT;
const color = alerta ? '#e67e22' : '#2980b9';
const icon = alerta ? '\u26a0' : '\u2192';

let html = '<div style="text-align:center;padding:10px">' +
  '<span style="font-size:22px;color:' + color + '">' + icon + ' Pr\u00f3xima lectura estimada</span><br>' +
  '<span style="font-size:28px;font-weight:bold;color:#333">Pulso: ' + pulsoPred + ' bpm</span><br>';

if (tempPred !== null) {
    html += '<span style="font-size:28px;font-weight:bold;color:#333">Temp: ' + tempPred + ' \u00b0C</span><br>';
}

html += '<span style="font-size:14px;color:#888">Actual: ' + (orig.pulso || '?') + ' bpm | Temp: ' + (orig.temperatura || '?') + '\u00b0C</span>' +
  '</div>';

msg.payload = html;
return msg;

node.warn('FF Router recibió: ' + JSON.stringify({net:!!msg.net, decision:msg.decision, runData:msg.runData}));
if (msg.net) {
    flow.set('ff_trained', true);
    node.status({fill:'green',shape:'dot',text:'Entrenada'});
    return null;
}
if (msg.decision) {
    return msg;
}
return null;

if (msg.net) {
    flow.set('lstm_trained', true);
    node.status({fill:'green',shape:'dot',text:'Entrenada'});
    node.warn('LSTM entrenada OK');
    return null;
}
if (msg.decision !== undefined && msg.decision !== null) {
    return msg;
}
return null;

const results = msg.payload;
const WINDOW = 4;
const MIN_SEQUENCES = 6;
const MAX_SEQUENCES = 80;

const DEFAULT_TRAIN = [
    [{pulso:0.35,temp:0.730},{pulso:0.36,temp:0.732},{pulso:0.35,temp:0.730},{pulso:0.355,temp:0.731}],
    [{pulso:0.40,temp:0.734},{pulso:0.39,temp:0.735},{pulso:0.41,temp:0.734},{pulso:0.40,temp:0.736}],
    [{pulso:0.31,temp:0.726},{pulso:0.32,temp:0.727},{pulso:0.31,temp:0.726},{pulso:0.315,temp:0.726}],
    [{pulso:0.375,temp:0.732},{pulso:0.38,temp:0.733},{pulso:0.37,temp:0.732},{pulso:0.375,temp:0.732}],
    [{pulso:0.325,temp:0.730},{pulso:0.345,temp:0.731},{pulso:0.36,temp:0.730},{pulso:0.375,temp:0.731}],
    [{pulso:0.39,temp:0.728},{pulso:0.37,temp:0.729},{pulso:0.36,temp:0.728},{pulso:0.35,temp:0.728}],
    [{pulso:0.29,temp:0.724},{pulso:0.31,temp:0.726},{pulso:0.33,temp:0.728},{pulso:0.34,temp:0.730}],
    [{pulso:0.425,temp:0.736},{pulso:0.42,temp:0.735},{pulso:0.43,temp:0.736},{pulso:0.425,temp:0.736}]
];

if (!Array.isArray(results) || results.length === 0) {
    node.warn("LSTM: sin datos de InfluxDB, usando fallback humano normal");
    msg.trainData = DEFAULT_TRAIN;
    return msg;
}

const pulseData = results.filter(r => r.sensor === 'pulso')
    .sort((a,b) => new Date(a._time) - new Date(b._time));
const tempData = results.filter(r => r.sensor === 'temperatura')
    .sort((a,b) => new Date(a._time) - new Date(b._time));
const minLen = Math.min(pulseData.length, tempData.length);

if (minLen < WINDOW + 1) {
    node.warn("LSTM: datos pareados insuficientes (" + minLen + "), usando fallback");
    msg.trainData = DEFAULT_TRAIN;
    return msg;
}

const paired = [];
for (let i = 0; i < minLen; i++) {
    paired.push({
        pulso: Number(pulseData[i]._value) / 200,
        temp: Number(tempData[i]._value) / 50
    });
}

const sequences = [];
for (let i = 0; i <= paired.length - WINDOW; i++) {
    sequences.push(paired.slice(i, i + WINDOW));
}

if (sequences.length < MIN_SEQUENCES) {
    node.warn("LSTM: pocas secuencias (" + sequences.length + "), usando fallback");
    msg.trainData = DEFAULT_TRAIN;
    return msg;
}

const trimmed = sequences.length > MAX_SEQUENCES
    ? sequences.slice(-MAX_SEQUENCES) : sequences;
node.warn("LSTM: entrenando con " + trimmed.length + " secuencias (pulso+temp) de InfluxDB");
msg.trainData = trimmed;
return msg;

const data = msg.payload;
const pulso = Number(data.pulso);
const temperatura = Number(data.temperatura);
if (isNaN(pulso) || isNaN(temperatura)) return null;
msg.pulso = pulso;
msg.temperatura = temperatura;
return msg;
